import{_ as o,o as t,c as d,a3 as c}from"./chunks/framework.I6s8z2kk.js";const h=JSON.parse('{"title":"Billing and subscriptions","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/billing.md","filePath":"dev/domain/billing.md"}'),i={name:"dev/domain/billing.md"};function a(n,e,s,r,l,p){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="billing-and-subscriptions" tabindex="-1">Billing and subscriptions <a class="header-anchor" href="#billing-and-subscriptions" aria-label="Permalink to &quot;Billing and subscriptions&quot;">​</a></h1><p>The <strong>Billing</strong> module sells <strong>plans</strong> to centers as <strong>subscriptions</strong>. It is separate from client purchases.</p><h2 id="model" tabindex="-1">Model <a class="header-anchor" href="#model" aria-label="Permalink to &quot;Model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Plan</strong></td><td><code>name</code>, <code>slug</code>, <code>description</code>, <code>price</code>, <code>billing_interval</code> (<code>monthly</code> or <code>yearly</code>), <code>trial_days</code>, <code>status</code> (<code>active</code> or <code>in_active</code>), <code>display_features</code></td></tr><tr><td><strong>Feature</strong> / <strong>Limit</strong></td><td>The catalog a plan is built from (<code>PlanFeature</code>, <code>PlanLimit</code>)</td></tr><tr><td><strong>Subscription</strong></td><td>A center&#39;s subscription to a plan. Status <code>pending</code>, <code>trialing</code>, <code>active</code>, <code>canceled</code>, <code>expired</code></td></tr></tbody></table><h2 id="subscription-lifecycle" tabindex="-1">Subscription lifecycle <a class="header-anchor" href="#subscription-lifecycle" aria-label="Permalink to &quot;Subscription lifecycle&quot;">​</a></h2><p>Actions are <code>subscribe</code>, <code>cancel</code>, <code>renew</code> and <code>expire</code>.</p><ul><li><strong>Subscribe</strong> only to an <code>active</code> plan, with no <code>active</code> or <code>trialing</code> subscription to the same plan, holding a lock on the plan.</li><li>Status is <code>trialing</code> when <code>trial_days &gt; 0</code>, otherwise <code>active</code>.</li><li><code>ends_at = starts_at + one interval</code> (<code>addMonthsNoOverflow</code>).</li><li>Only the <strong>owner</strong> cancels <code>active</code> or <code>trialing</code> subscriptions.</li><li><strong>Renew</strong> creates a new row from the previous <code>ends_at</code>, with no trial.</li><li>Billing has <strong>no VAT, invoices or proration</strong>.</li><li><code>billing:release-unpaid</code> runs every 5 minutes and releases unpaid subscription holds.</li></ul><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Not versioned</p><p>The Billing routes are <strong>not</strong> under <code>/api/v1</code>. They live under <code>/api/&lt;actor&gt;/...</code>.</p></div><table tabindex="0"><thead><tr><th>Surface</th><th>Endpoints</th></tr></thead><tbody><tr><td>Admin catalog</td><td><code>api/admin/plans</code> (CRUD, <code>PATCH {plan}/status</code>, attach and detach <code>features</code> and <code>limits</code>), <code>api/admin/features</code> and <code>api/admin/limits</code> (CRUD). Permissions <code>plans.view_any</code>, <code>plans.create</code>, <code>plans.update</code>, <code>plans.delete</code>; the feature and limit catalog needs <code>plans.manage_catalog</code>.</td></tr><tr><td>Admin subscriptions</td><td><code>api/v1/admin/subscriptions</code> (list, show), <code>api/v1/admin/centers/{center}/subscription</code> (show, change). Needs <code>subscriptions.view_any</code> and <code>subscriptions.change</code>. The list takes <code>sort</code> (<code>AdminSubscriptionQuery::SORTS</code>): <code>starts_at</code> or <code>ends_at</code>, <code>-</code> for descending; newest first without it.</td></tr><tr><td>Center</td><td><code>api/center/plans</code> (catalog, list and show), <code>api/center/subscriptions</code> (list, <code>current</code>, subscribe, cancel with <code>DELETE {subscription}</code>)</td></tr></tbody></table><p>Subscription payments use the same gateways as purchases; gateway code must not reference Subscription. See <a href="./purchase">Purchases and payments</a>.</p>',11)])])}const b=o(i,[["render",a]]);export{h as __pageData,b as default};
